function checkEngine(temp) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (temp > 90) reject(new Error("Motor çok sıcak!"));
      else resolve("Motor hazır");
    }, 50);
  });
}

async function preflight(temp) {
  // try / catch ile await checkEngine(temp)
  try {
    return await checkEngine(temp);
  } catch (error) {
    return "Uyarı: " + error.message;
  }
}

console.log(await preflight(60));
console.log(await preflight(120));

check.js:
assert(await preflight(60) === "Motor hazır", "preflight(60) 'Motor hazır' döndürmeli.");
let hot;
try {
  hot = await preflight(120);
} catch (e) {
  assert(false, "preflight hatayı dışarı fırlatmamalı; try/catch ile yakala.");
}
assert(hot === "Uyarı: Motor çok sıcak!", "preflight(120) 'Uyarı: Motor çok sıcak!' döndürmeli.");
assert(await preflight(90) === "Motor hazır" && await preflight(91) === "Uyarı: Motor çok sıcak!", "Sonuç checkEngine'den gelmeli.");
assert(_lines.includes("Uyarı: Motor çok sıcak!"), "Çıktıda 'Uyarı: Motor çok sıcak!' görünmeli.");

