const LEVELS = {
  1: { seviye: 1, yildiz: 5, hiz: 2 },
  2: { seviye: 2, yildiz: 8, hiz: 3 },
  3: { seviye: 3, yildiz: 12, hiz: 4 },
};

function loadLevel(n) {
  // 100 ms sonra LEVELS[n] ile tamamlanan (yoksa reddedilen) bir Promise döndür
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (LEVELS[n]) resolve(LEVELS[n]);
      else reject(new Error(`Seviye bulunamadı: ${n}`));
    }, 100);
  });
}

async function startLevel(n) {
  const info = document.querySelector("#info");
  // yükleniyor yaz, await loadLevel(n), bilgiyi yaz; hatayı yakala
  info.textContent = "Seviye yükleniyor…";
  try {
    const level = await loadLevel(n);
    info.textContent = `Seviye ${level.seviye}: ${level.yildiz} yıldız, hız ${level.hiz}`;
  } catch (error) {
    info.textContent = `Hata: ${error.message}`;
  }
}

startLevel(1);

check.js:
await sleep(150);
const p = loadLevel(2);
assert(p && typeof p.then === "function", "loadLevel(n) bir Promise döndürmeli.");
const t0 = Date.now();
const lv = await p;
assert(same(lv, LEVELS[2]), "loadLevel(2) LEVELS[2] ile tamamlanmalı.");
assert(Date.now() - t0 >= 60, "loadLevel 100 ms sonra tamamlanmalı (setTimeout).");
let err = null;
await loadLevel(7).then(() => {}, (e) => { err = e; });
assert(err && err.message === "Seviye bulunamadı: 7", "Olmayan seviye 'Seviye bulunamadı: 7' hatasıyla reddedilmeli (reject(new Error(...))).");
const q = startLevel(3);
assert(/yükleniyor/.test($("#info").textContent), "startLevel önce #info'ya 'Seviye yükleniyor…' yazmalı.");
await q;
assert($("#info").textContent.trim() === "Seviye 3: 12 yıldız, hız 4", "Yüklenince #info 'Seviye 3: 12 yıldız, hız 4' yazmalı.");
await startLevel(9);
assert($("#info").textContent.trim() === "Hata: Seviye bulunamadı: 9", "Hata olursa #info 'Hata: Seviye bulunamadı: 9' yazmalı.");

