const posts = ["İlk kodum", "Döngüler neden harika?", "Sitemi yayınladım"];

function wait(ms) {
  // Promise döndür
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function showPage() {
  // boşalt, yükleniyor göster, bekle, yazıları ekle, yükleniyor gizle
  const loader = document.querySelector("#loader");
  const content = document.querySelector("#content");
  content.innerHTML = "";
  loader.classList.remove("hidden");
  await wait(150);
  for (const title of posts) {
    const h3 = document.createElement("h3");
    h3.textContent = title;
    content.append(h3);
  }
  loader.classList.add("hidden");
}

showPage();

check.js:
await sleep(250);
const w = wait(10);
assert(w && typeof w.then === "function", "wait(ms) bir Promise döndürmeli.");
const t0 = Date.now();
await wait(100);
assert(Date.now() - t0 >= 80, "wait(100) yaklaşık 100 ms sonra tamamlanmalı.");
const p = showPage();
assert(!$("#loader").classList.contains("hidden"), "Beklerken #loader görünmeli (hidden sınıfını kaldır).");
assert($$("#content h3").length === 0, "Beklerken #content boş olmalı: önce boşalt, yazıları beklemeden sonra ekle.");
await p;
assert($("#loader").classList.contains("hidden"), "Yükleme bitince #loader'a tekrar hidden sınıfı verilmeli.");
const titles = $$("#content h3").map((h) => h.textContent.trim());
assert(same(titles, posts), "#content'te posts dizisindeki her başlık için bir <h3> olmalı.");
posts.push("Yeni yazı");
await showPage();
assert($$("#content h3").length === 4, "showPage() her çağrıda içeriği baştan kurmalı (önce #content'i boşalt).");

