const saveBtn = document.querySelector("#save");
const statusText = document.querySelector("#status");

function saveTasks(tasks) {
  // 100 ms sonra localStorage'a yazan bir Promise döndür
  return new Promise((resolve) => {
    setTimeout(() => {
      localStorage.setItem("tasks", JSON.stringify(tasks));
      resolve();
    }, 100);
  });
}

// #save tıklanınca: topla, Kaydediliyor…, await, Kaydedildi
saveBtn.addEventListener("click", async () => {
  const tasks = Array.from(document.querySelectorAll("#list li")).map((li) => li.textContent);
  statusText.textContent = "Kaydediliyor…";
  saveBtn.disabled = true;
  await saveTasks(tasks);
  statusText.textContent = "Kaydedildi";
  saveBtn.disabled = false;
});

check.js:
localStorage.removeItem("tasks");
const p = saveTasks(["X"]);
assert(p && typeof p.then === "function", "saveTasks bir Promise döndürmeli.");
assert(localStorage.getItem("tasks") === null, "Kayıt hemen değil, 100 ms sonra yapılmalı (setTimeout).");
await p;
assert(localStorage.getItem("tasks") === '["X"]', "saveTasks görevleri JSON olarak 'tasks' anahtarına yazmalı.");
localStorage.removeItem("tasks");
click("#save");
assert(/Kaydediliyor/.test($("#status").textContent), "Tıklayınca #status 'Kaydediliyor…' olmalı.");
assert($("#save").disabled === true, "Kaydederken düğme devre dışı olmalı (disabled = true).");
await sleep(250);
assert($("#status").textContent.trim() === "Kaydedildi", "Kayıt bitince #status 'Kaydedildi' olmalı.");
assert($("#save").disabled === false, "Kayıt bitince düğme tekrar açılmalı.");
assert(same(JSON.parse(localStorage.getItem("tasks") || "null"), ["Fizik tekrarı", "Kitap okuma"]), "Listedeki görevler kaydedilmeli: [\"Fizik tekrarı\", \"Kitap okuma\"].");
const li = document.createElement("li");
li.textContent = "Kimya";
$("#list").append(li);
click("#save");
await sleep(250);
assert(JSON.parse(localStorage.getItem("tasks") || "[]").length === 3, "Görevler her tıklamada listeden yeniden toplanmalı.");

