project_task.solution:
const QUESTIONS = [
  { soru: "Ay, hangi gezegenin uydusudur?", secenekler: ["Mars", "Dünya", "Jüpiter"], dogru: 1 },
  { soru: "Kızıl gezegen hangisidir?", secenekler: ["Venüs", "Mars", "Merkür"], dogru: 1 },
  { soru: "Halkalarıyla ünlü gezegen hangisidir?", secenekler: ["Satürn", "Mars", "Uranüs"], dogru: 0 },
];

function loadQuestions() {
  // 150 ms sonra QUESTIONS ile tamamlanan bir Promise döndür
  return new Promise((resolve) => {
    setTimeout(() => resolve(QUESTIONS), 150);
  });
}

async function start() {
  // yükleniyor yaz, düğmeyi gizle, await, ilk soruyu ve sayıyı yaz
  const question = document.querySelector("#question");
  question.textContent = "Sorular yükleniyor…";
  document.querySelector("#start").hidden = true;
  const questions = await loadQuestions();
  question.textContent = questions[0].soru;
  document.querySelector("#count").textContent = `${questions.length} soru`;
}

// #start düğmesini bağla
document.querySelector("#start").addEventListener("click", start);

check.js:
const p = loadQuestions();
assert(p && typeof p.then === "function", "loadQuestions() bir Promise döndürmeli.");
const t0 = Date.now();
const qs = await p;
assert(qs === QUESTIONS || same(qs, QUESTIONS), "loadQuestions() QUESTIONS dizisiyle tamamlanmalı.");
assert(Date.now() - t0 >= 100, "Sorular 150 ms sonra gelmeli (setTimeout).");
click("#start");
assert(/yükleniyor/.test($("#question").textContent), "Başlatınca #question 'Sorular yükleniyor…' yazmalı.");
assert($("#start").hidden === true, "Başlatınca #start düğmesi gizlenmeli (hidden = true).");
await sleep(300);
assert($("#question").textContent.trim() === QUESTIONS[0].soru, "Yüklenince #question ilk sorunun metnini göstermeli.");
assert($("#count").textContent.trim() === "3 soru", "#count '3 soru' yazmalı.");
QUESTIONS.unshift({ soru: "Güneş bir yıldız mıdır?", secenekler: ["Evet", "Hayır"], dogru: 0 });
await start();
assert($("#question").textContent.trim() === "Güneş bir yıldız mıdır?" && $("#count").textContent.trim() === "4 soru", "İlk soru ve sayı yüklenen diziden gelmeli (elle yazma).");
